s15-graph-and-types.code:
// Approach: A graph has vertices and edges; directed edges go one way, while undirected edges are
//   stored in both directions.
#include <stdexcept>
#include <vector>
using namespace std;
class Graph {
    vector<vector<int>> adj;
    bool directed;
public:
    Graph(int vertices, bool directed)
        : adj(vertices < 0 ? 0 : vertices), directed(directed) {
        if (vertices < 0) throw invalid_argument("negative vertex count");
    }
    void addEdge(int from, int to) {
        if (from < 0 || to < 0 || from >= (int)adj.size() || to >= (int)adj.size())
            throw out_of_range("vertex");
        adj[from].push_back(to);
        if (!directed) adj[to].push_back(from); // two-way edge
    }
    const vector<vector<int>>& neighbors() const { return adj; }
};

s15-graph-representation-c.code:
// Approach: For a sparse undirected graph, an adjacency list stores each edge at both endpoints and
//   uses O(V+E) space.
#include <stdexcept>
#include <utility>
#include <vector>
using namespace std;
vector<vector<int>> undirectedAdjacencyList(
    int vertices, const vector<pair<int,int>>& edges) {
    if (vertices < 0) throw invalid_argument("negative vertex count");
    vector<vector<int>> adj(vertices);
    for (auto [u, v] : edges) {
        if (u < 0 || v < 0 || u >= vertices || v >= vertices)
            throw out_of_range("vertex");
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

s15-graph-representation-java.code:
// Approach: This roadmap lesson uses Java collections; the equivalent C++ representation is a vector
//   of neighbor vectors, one per vertex.
#include <stdexcept>
#include <utility>
#include <vector>
using namespace std;
vector<vector<int>> directedAdjacencyList(
    int vertices, const vector<pair<int,int>>& edges) {
    if (vertices < 0) throw invalid_argument("negative vertex count");
    vector<vector<int>> adj(vertices);
    for (auto [from, to] : edges) {
        if (from < 0 || to < 0 || from >= vertices || to >= vertices)
            throw out_of_range("vertex");
        adj[from].push_back(to); // directed: no reverse edge
    }
    return adj;
}

s15-connected-components-logic-explanati.code:
// Approach: Start a traversal from each unvisited vertex. Every completed traversal marks exactly one
//   connected component.
#include <queue>
#include <vector>
using namespace std;
int countComponents(const vector<vector<int>>& adj) {
    int n = (int)adj.size(), count = 0;
    vector<char> seen(n, false);
    for (int start = 0; start < n; ++start) {
        if (seen[start]) continue;
        ++count; // a new unvisited start means a new component
        queue<int> q;
        q.push(start);
        seen[start] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) if (!seen[v]) {
                seen[v] = true;
                q.push(v);
            }
        }
    }
    return count; // adjacency list describes an undirected graph
}

s15-bfs.code:
// Approach: A queue visits all vertices one edge away before moving to the next level. Restart at
//   unvisited vertices to include disconnected components.
#include <queue>
#include <vector>
using namespace std;
vector<int> bfsAll(const vector<vector<int>>& adj) {
    vector<int> order;
    vector<char> seen(adj.size(), false);
    for (int start = 0; start < (int)adj.size(); ++start) {
        if (seen[start]) continue;
        queue<int> q;
        q.push(start);
        seen[start] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            order.push_back(u);
            for (int v : adj[u]) if (!seen[v]) {
                seen[v] = true; // mark when enqueued, not when popped
                q.push(v);
            }
        }
    }
    return order;
}

s15-dfs.code:
// Approach: Depth-first search follows one path until it cannot continue, then backtracks. Restart to
//   cover disconnected components.
#include <vector>
using namespace std;
void dfsVisit(int u, const vector<vector<int>>& adj,
              vector<char>& seen, vector<int>& order) {
    seen[u] = true;
    order.push_back(u);
    for (int v : adj[u]) if (!seen[v])
        dfsVisit(v, adj, seen, order);
}
vector<int> dfsAll(const vector<vector<int>>& adj) {
    vector<char> seen(adj.size(), false);
    vector<int> order;
    for (int u = 0; u < (int)adj.size(); ++u)
        if (!seen[u]) dfsVisit(u, adj, seen, order);
    return order;
}

s15-number-of-provinces-leetcode.code:
// Approach: Treat the symmetric connectivity matrix as an undirected graph. DFS from each unvisited
//   city to count provinces.
#include <vector>
using namespace std;
void provinceDfs(int city, const vector<vector<int>>& connected,
                 vector<char>& seen) {
    seen[city] = true;
    for (int other = 0; other < (int)connected.size(); ++other)
        if (connected[city][other] && !seen[other])
            provinceDfs(other, connected, seen);
}
int findCircleNum(const vector<vector<int>>& connected) {
    int n = (int)connected.size(), provinces = 0;
    vector<char> seen(n, false);
    for (int city = 0; city < n; ++city)
        if (!seen[city]) {
            ++provinces;
            provinceDfs(city, connected, seen);
        }
    return provinces;
}

s15-connected-components-problem-in-matr.code:
// Approach: For an undirected adjacency matrix, BFS from each unseen vertex and collect the vertices
//   of that connected component.
#include <queue>
#include <vector>
using namespace std;
vector<vector<int>> matrixComponents(const vector<vector<int>>& matrix) {
    int n = (int)matrix.size();
    vector<char> seen(n, false);
    vector<vector<int>> components;
    for (int start = 0; start < n; ++start) {
        if (seen[start]) continue;
        vector<int> component;
        queue<int> q;
        q.push(start);
        seen[start] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            component.push_back(u);
            for (int v = 0; v < n; ++v)
                if (matrix[u][v] && !seen[v]) {
                    seen[v] = true;
                    q.push(v);
                }
        }
        components.push_back(component);
    }
    return components;
}

s15-rotten-oranges.code:
// Approach: Put all initially rotten oranges in one BFS queue. Each BFS layer rots adjacent fresh
//   oranges one minute later.
#include <queue>
#include <utility>
#include <vector>
using namespace std;
int orangesRotting(vector<vector<int>> grid) {
    int rows = (int)grid.size();
    if (!rows) return 0;
    int cols = (int)grid[0].size(), fresh = 0;
    queue<pair<int,int>> q;
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < cols; ++c) {
            if (grid[r][c] == 2) q.push({r, c});
            else if (grid[r][c] == 1) ++fresh;
        }
    int minutes = 0;
    const int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    while (!q.empty() && fresh > 0) {
        int width = (int)q.size();
        ++minutes; // this layer infects neighbors in one minute
        while (width--) {
            auto [r, c] = q.front(); q.pop();
            for (int i = 0; i < 4; ++i) {
                int nr = r + dr[i], nc = c + dc[i];
                if (nr < 0 || nc < 0 || nr >= rows || nc >= cols
                    || grid[nr][nc] != 1) continue;
                grid[nr][nc] = 2;
                --fresh;
                q.push({nr, nc});
            }
        }
    }
    return fresh == 0 ? minutes : -1;
}

s15-flood-fill.code:
// Approach: Start from the chosen cell and BFS only through cells of its original color, recoloring
//   each when it is enqueued.
#include <queue>
#include <utility>
#include <vector>
using namespace std;
vector<vector<int>> floodFill(vector<vector<int>> image,
                              int startRow, int startCol, int newColor) {
    int rows = (int)image.size();
    if (!rows || startRow < 0 || startRow >= rows
        || startCol < 0 || startCol >= (int)image[0].size()) return image;
    int cols = (int)image[0].size();
    int original = image[startRow][startCol];
    if (original == newColor) return image;
    queue<pair<int,int>> q;
    q.push({startRow, startCol});
    image[startRow][startCol] = newColor;
    const int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr < 0 || nc < 0 || nr >= rows || nc >= cols
                || image[nr][nc] != original) continue;
            image[nr][nc] = newColor; // mark before enqueue to avoid repeats
            q.push({nr, nc});
        }
    }
    return image;
}

s15-cycle-detection-in-unirected-graph-b.code:
// Approach: In an undirected BFS, a previously visited neighbor is a cycle only when it is not the
//   current node's parent.
#include <queue>
#include <utility>
#include <vector>
using namespace std;
bool hasUndirectedCycleBfs(const vector<vector<int>>& adj) {
    vector<char> seen(adj.size(), false);
    for (int start = 0; start < (int)adj.size(); ++start) {
        if (seen[start]) continue;
        queue<pair<int,int>> q;
        q.push({start, -1});
        seen[start] = true;
        while (!q.empty()) {
            auto [u, parent] = q.front(); q.pop();
            for (int v : adj[u]) {
                if (!seen[v]) {
                    seen[v] = true;
                    q.push({v, u});
                } else if (v != parent) return true;
            }
        }
    }
    return false; // assumes a simple undirected graph
}

s15-cycle-detection-in-undirected-graph-.code:
// Approach: During DFS, an edge to an already visited node other than the parent closes a cycle.
#include <vector>
using namespace std;
bool cycleDfs(int u, int parent, const vector<vector<int>>& adj,
              vector<char>& seen) {
    seen[u] = true;
    for (int v : adj[u]) {
        if (!seen[v]) {
            if (cycleDfs(v, u, adj, seen)) return true;
        } else if (v != parent) return true;
    }
    return false;
}
bool hasUndirectedCycleDfs(const vector<vector<int>>& adj) {
    vector<char> seen(adj.size(), false);
    for (int u = 0; u < (int)adj.size(); ++u)
        if (!seen[u] && cycleDfs(u, -1, adj, seen)) return true;
    return false; // assumes a simple undirected graph
}

s15-0-1-matrix-bfs-problem.code:
// Approach: Start BFS simultaneously from every zero. The first time a one-cell is reached gives its
//   shortest distance to any zero.
#include <queue>
#include <utility>
#include <vector>
using namespace std;
vector<vector<int>> updateMatrix(const vector<vector<int>>& grid) {
    int rows = (int)grid.size();
    if (!rows) return {};
    int cols = (int)grid[0].size();
    vector<vector<int>> distance(rows, vector<int>(cols, -1));
    queue<pair<int,int>> q;
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < cols; ++c)
            if (grid[r][c] == 0) {
                distance[r][c] = 0;
                q.push({r, c});
            }
    const int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr < 0 || nc < 0 || nr >= rows || nc >= cols
                || distance[nr][nc] != -1) continue;
            distance[nr][nc] = distance[r][c] + 1;
            q.push({nr, nc});
        }
    }
    return distance; // -1 if the matrix contains no zero
}

s15-surrounded-regions-dfs.code:
// Approach: Mark every 'O' connected to a boundary 'O' as safe. Afterward flip only unmarked 'O'
//   cells to 'X'.
#include <vector>
using namespace std;
void markBoundary(vector<vector<char>>& board, int r, int c) {
    int rows = (int)board.size(), cols = (int)board[0].size();
    if (r < 0 || c < 0 || r >= rows || c >= cols || board[r][c] != 'O')
        return;
    board[r][c] = '#'; // temporarily protect boundary-connected cells
    markBoundary(board, r + 1, c);
    markBoundary(board, r - 1, c);
    markBoundary(board, r, c + 1);
    markBoundary(board, r, c - 1);
}
void solveSurrounded(vector<vector<char>>& board) {
    if (board.empty() || board[0].empty()) return;
    int rows = (int)board.size(), cols = (int)board[0].size();
    for (int r = 0; r < rows; ++r) {
        markBoundary(board, r, 0);
        markBoundary(board, r, cols - 1);
    }
    for (int c = 0; c < cols; ++c) {
        markBoundary(board, 0, c);
        markBoundary(board, rows - 1, c);
    }
    for (auto& row : board)
        for (char& cell : row)
            if (cell == 'O') cell = 'X';
            else if (cell == '#') cell = 'O';
}

s15-number-of-enclaves-flood-fill-implem.code:
// Approach: Flood-fill all land connected to a boundary cell. The land left afterward is enclosed and
//   can be counted.
#include <queue>
#include <utility>
#include <vector>
using namespace std;
int numEnclaves(vector<vector<int>> grid) {
    int rows = (int)grid.size();
    if (!rows) return 0;
    int cols = (int)grid[0].size();
    queue<pair<int,int>> q;
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < cols; ++c)
            if (grid[r][c] == 1 &&
                (r == 0 || c == 0 || r == rows - 1 || c == cols - 1)) {
                grid[r][c] = 0;
                q.push({r, c});
            }
    const int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr < 0 || nc < 0 || nr >= rows || nc >= cols
                || grid[nr][nc] != 1) continue;
            grid[nr][nc] = 0; // remove boundary-reachable land
            q.push({nr, nc});
        }
    }
    int enclosed = 0;
    for (const auto& row : grid)
        for (int cell : row) enclosed += cell == 1;
    return enclosed;
}

s15-word-ladder-1.code:
// Approach: BFS words differing by one character. The first time endWord is reached gives the
//   shortest transformation length.
#include <queue>
#include <string>
#include <unordered_set>
#include <vector>
using namespace std;
int ladderLength(const string& beginWord, const string& endWord,
                 const vector<string>& wordList) {
    if (beginWord == endWord) return 1;
    unordered_set<string> available(wordList.begin(), wordList.end());
    if (!available.count(endWord)) return 0;
    queue<pair<string,int>> q;
    q.push({beginWord, 1});
    available.erase(beginWord);
    while (!q.empty()) {
        auto [word, length] = q.front(); q.pop();
        for (int i = 0; i < (int)word.size(); ++i) {
            string next = word;
            for (char ch = 'a'; ch <= 'z'; ++ch) {
                if (ch == word[i]) continue;
                next[i] = ch;
                if (next == endWord) return length + 1;
                if (available.erase(next)) q.push({next, length + 1});
            }
        }
    }
    return 0;
}

s15-word-ladder-2.code:
// Approach: BFS assigns shortest distances and records every parent reaching a word at that distance.
//   Backtrack from the end through those parents to list all shortest ladders.
#include <algorithm>
#include <queue>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <vector>
using namespace std;
void ladderPaths(const string& word, const string& start,
                 const unordered_map<string, vector<string>>& parents,
                 vector<string>& reversed, vector<vector<string>>& answer) {
    if (word == start) {
        answer.emplace_back(reversed.rbegin(), reversed.rend());
        return;
    }
    auto it = parents.find(word);
    if (it == parents.end()) return;
    for (const string& previous : it->second) {
        reversed.push_back(previous);
        ladderPaths(previous, start, parents, reversed, answer);
        reversed.pop_back();
    }
}
vector<vector<string>> findLadders(const string& beginWord,
                                   const string& endWord,
                                   const vector<string>& wordList) {
    if (beginWord == endWord) return {{beginWord}};
    unordered_set<string> dictionary(wordList.begin(), wordList.end());
    if (!dictionary.count(endWord)) return {};
    unordered_map<string,int> distance;
    unordered_map<string,vector<string>> parents;
    queue<string> q;
    q.push(beginWord);
    distance[beginWord] = 0;
    int shortest = -1;
    while (!q.empty()) {
        string word = q.front(); q.pop();
        int steps = distance[word];
        if (shortest != -1 && steps >= shortest) continue;
        for (int i = 0; i < (int)word.size(); ++i) {
            string next = word;
            for (char ch = 'a'; ch <= 'z'; ++ch) {
                if (ch == word[i]) continue;
                next[i] = ch;
                if (!dictionary.count(next)) continue;
                auto it = distance.find(next);
                if (it == distance.end()) {
                    distance[next] = steps + 1;
                    parents[next].push_back(word);
                    q.push(next);
                    if (next == endWord) shortest = steps + 1;
                } else if (it->second == steps + 1) {
                    parents[next].push_back(word); // another shortest parent
                }
            }
        }
    }
    vector<vector<string>> answer;
    if (shortest == -1) return answer;
    vector<string> reversed{endWord};
    ladderPaths(endWord, beginWord, parents, reversed, answer);
    return answer;
}

s15-number-of-distinct-islands-dfs-multi.code:
// Approach: Record every island cell as an offset from its starting cell. Translation-equivalent
//   islands produce the same sorted offset list.
#include <algorithm>
#include <set>
#include <utility>
#include <vector>
using namespace std;
void islandShape(const vector<vector<int>>& grid, int r, int c,
                 int baseR, int baseC, vector<vector<char>>& seen,
                 vector<pair<int,int>>& shape) {
    int rows = (int)grid.size(), cols = (int)grid[0].size();
    if (r < 0 || c < 0 || r >= rows || c >= cols
        || grid[r][c] == 0 || seen[r][c]) return;
    seen[r][c] = true;
    shape.push_back({r - baseR, c - baseC});
    islandShape(grid, r + 1, c, baseR, baseC, seen, shape);
    islandShape(grid, r - 1, c, baseR, baseC, seen, shape);
    islandShape(grid, r, c + 1, baseR, baseC, seen, shape);
    islandShape(grid, r, c - 1, baseR, baseC, seen, shape);
}
int countDistinctIslands(const vector<vector<int>>& grid) {
    if (grid.empty() || grid[0].empty()) return 0;
    int rows = (int)grid.size(), cols = (int)grid[0].size();
    vector<vector<char>> seen(rows, vector<char>(cols));
    set<vector<pair<int,int>>> shapes;
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < cols; ++c)
            if (grid[r][c] && !seen[r][c]) {
                vector<pair<int,int>> shape;
                islandShape(grid, r, c, r, c, seen, shape);
                sort(shape.begin(), shape.end()); // traversal order is irrelevant
                shapes.insert(shape);
            }
    return (int)shapes.size();
}

s15-bipartite-graph-dfs.code:
// Approach: Color each component with two alternating colors. An edge joining equal colors proves the
//   graph is not bipartite.
#include <vector>
using namespace std;
bool colorDfs(int u, int color, const vector<vector<int>>& adj,
              vector<int>& colors) {
    colors[u] = color;
    for (int v : adj[u]) {
        if (colors[v] == color) return false;
        if (colors[v] == 0 && !colorDfs(v, -color, adj, colors))
            return false;
    }
    return true;
}
bool isBipartite(const vector<vector<int>>& adj) {
    vector<int> colors(adj.size(), 0);
    for (int u = 0; u < (int)adj.size(); ++u)
        if (colors[u] == 0 && !colorDfs(u, 1, adj, colors))
            return false;
    return true;
}

s15-cycle-detection-in-directed-graph-df.code:
// Approach: Mark DFS states as unseen, active, or finished. An edge to an active node is a back edge
//   and forms a directed cycle.
#include <vector>
using namespace std;
bool directedCycleDfs(int u, const vector<vector<int>>& adj,
                      vector<char>& state) {
    state[u] = 1; // active in the current DFS path
    for (int v : adj[u]) {
        if (state[v] == 1) return true;
        if (state[v] == 0 && directedCycleDfs(v, adj, state)) return true;
    }
    state[u] = 2; // fully explored
    return false;
}
bool hasDirectedCycle(const vector<vector<int>>& adj) {
    vector<char> state(adj.size(), 0);
    for (int u = 0; u < (int)adj.size(); ++u)
        if (state[u] == 0 && directedCycleDfs(u, adj, state))
            return true;
    return false;
}

s15-topo-sort.code:
// Approach: In a DAG, append each node after recursively visiting its outgoing neighbors, then
//   reverse the postorder. An active back edge means no topological order exists.
#include <algorithm>
#include <vector>
using namespace std;
bool topoDfs(int u, const vector<vector<int>>& adj,
             vector<char>& state, vector<int>& order) {
    state[u] = 1;
    for (int v : adj[u]) {
        if (state[v] == 1) return false; // directed cycle
        if (state[v] == 0 && !topoDfs(v, adj, state, order)) return false;
    }
    state[u] = 2;
    order.push_back(u);
    return true;
}
vector<int> topoSortDfs(const vector<vector<int>>& adj) {
    vector<char> state(adj.size(), 0);
    vector<int> order;
    for (int u = 0; u < (int)adj.size(); ++u)
        if (state[u] == 0 && !topoDfs(u, adj, state, order))
            return {};
    reverse(order.begin(), order.end());
    return order;
}

s15-kahn-s-algorithm.code:
// Approach: Repeatedly take a zero-indegree vertex, output it, and decrement its neighbors'
//   indegrees. Fewer than V outputs means a cycle.
#include <queue>
#include <vector>
using namespace std;
vector<int> topoSortKahn(const vector<vector<int>>& adj) {
    int n = (int)adj.size();
    vector<int> indegree(n);
    for (const auto& neighbors : adj)
        for (int v : neighbors) ++indegree[v];
    queue<int> ready;
    for (int u = 0; u < n; ++u)
        if (indegree[u] == 0) ready.push(u);
    vector<int> order;
    while (!ready.empty()) {
        int u = ready.front(); ready.pop();
        order.push_back(u);
        for (int v : adj[u])
            if (--indegree[v] == 0) ready.push(v);
    }
    return (int)order.size() == n ? order : vector<int>{};
}

s15-cycle-detection-in-directed-graph-bf.code:
// Approach: Kahn's zero-indegree process removes every vertex of a DAG. If any vertices remain, they
//   participate in or depend on a directed cycle.
#include <queue>
#include <vector>
using namespace std;
bool hasDirectedCycleKahn(const vector<vector<int>>& adj) {
    int n = (int)adj.size();
    vector<int> indegree(n);
    for (const auto& neighbors : adj)
        for (int v : neighbors) ++indegree[v];
    queue<int> q;
    for (int u = 0; u < n; ++u) if (indegree[u] == 0) q.push(u);
    int removed = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        ++removed;
        for (int v : adj[u])
            if (--indegree[v] == 0) q.push(v);
    }
    return removed != n;
}

s15-course-schedule-i.code:
// Approach: Add prerequisite→course edges. All courses can finish exactly when Kahn's algorithm
//   removes every vertex.
#include <queue>
#include <utility>
#include <vector>
using namespace std;
bool canFinish(int courses, const vector<pair<int,int>>& prerequisites) {
    vector<vector<int>> adj(courses);
    vector<int> indegree(courses);
    for (auto [course, before] : prerequisites) {
        adj[before].push_back(course);
        ++indegree[course];
    }
    queue<int> q;
    for (int u = 0; u < courses; ++u)
        if (indegree[u] == 0) q.push(u);
    int completed = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        ++completed;
        for (int v : adj[u])
            if (--indegree[v] == 0) q.push(v);
    }
    return completed == courses;
}

