s15-find-eventual-safe-states.code:
// Approach: Reverse every edge and track original outdegree. Nodes with outdegree zero are safe;
//   removing them may make predecessors safe.
#include <algorithm>
#include <queue>
#include <vector>
using namespace std;
vector<int> eventualSafeNodes(const vector<vector<int>>& graph) {
    int n = (int)graph.size();
    vector<vector<int>> reverse(n);
    vector<int> outdegree(n);
    for (int u = 0; u < n; ++u) {
        outdegree[u] = (int)graph[u].size();
        for (int v : graph[u]) reverse[v].push_back(u);
    }
    queue<int> q;
    for (int u = 0; u < n; ++u)
        if (outdegree[u] == 0) q.push(u);
    vector<int> safe;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        safe.push_back(u);
        for (int previous : reverse[u])
            if (--outdegree[previous] == 0) q.push(previous);
    }
    sort(safe.begin(), safe.end());
    return safe;
}

s15-alien-dictionary.code:
// Approach: For adjacent dictionary words, the first differing letters define one ordering edge.
//   Topologically sort those letters; reject invalid prefixes or cycles.
#include <algorithm>
#include <functional>
#include <queue>
#include <string>
#include <unordered_set>
#include <vector>
using namespace std;
string alienOrder(const vector<string>& words, int alphabetSize) {
    if (alphabetSize < 0 || alphabetSize > 26) return "";
    vector<unordered_set<int>> adj(alphabetSize);
    vector<int> indegree(alphabetSize);
    for (const string& word : words)
        for (char ch : word)
            if (ch < 'a' || ch >= 'a' + alphabetSize) return "";
    for (int i = 1; i < (int)words.size(); ++i) {
        const string& a = words[i - 1];
        const string& b = words[i];
        int j = 0;
        while (j < (int)min(a.size(), b.size()) && a[j] == b[j]) ++j;
        if (j == (int)min(a.size(), b.size())) {
            if (a.size() > b.size()) return ""; // invalid prefix order
        } else {
            int from = a[j] - 'a', to = b[j] - 'a';
            if (adj[from].insert(to).second) ++indegree[to];
        }
    }
    priority_queue<int, vector<int>, greater<int>> ready;
    for (int u = 0; u < alphabetSize; ++u)
        if (indegree[u] == 0) ready.push(u);
    string order;
    while (!ready.empty()) {
        int u = ready.top(); ready.pop();
        order.push_back(char('a' + u));
        for (int v : adj[u])
            if (--indegree[v] == 0) ready.push(v);
    }
    return (int)order.size() == alphabetSize ? order : "";
}

s15-shortest-path-in-ug-with-unit-weight.code:
// Approach: Every edge costs one, so BFS first reaches each vertex along its shortest path.
#include <queue>
#include <utility>
#include <vector>
using namespace std;
vector<int> shortestUnitPaths(int n, const vector<pair<int,int>>& edges,
                              int source) {
    vector<vector<int>> adj(n);
    for (auto [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector<int> distance(n, -1);
    queue<int> q;
    distance[source] = 0;
    q.push(source);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) if (distance[v] == -1) {
            distance[v] = distance[u] + 1; // first BFS visit is shortest
            q.push(v);
        }
    }
    return distance;
}

s15-shortest-path-in-dag.code:
// Approach: Topologically order the DAG, then relax each outgoing edge once after its source has its
//   final shortest distance.
#include <algorithm>
#include <climits>
#include <queue>
#include <stdexcept>
#include <tuple>
#include <utility>
#include <vector>
using namespace std;
vector<long long> shortestDagPaths(int n,
    const vector<tuple<int,int,int>>& edges, int source) {
    vector<vector<pair<int,int>>> adj(n);
    vector<int> indegree(n);
    for (auto [u, v, weight] : edges) {
        adj[u].push_back({v, weight});
        ++indegree[v];
    }
    queue<int> q;
    for (int u = 0; u < n; ++u) if (indegree[u] == 0) q.push(u);
    vector<int> order;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        order.push_back(u);
        for (auto [v, weight] : adj[u])
            if (--indegree[v] == 0) q.push(v);
    }
    if ((int)order.size() != n) throw invalid_argument("graph is not a DAG");
    const long long INF = LLONG_MAX / 4;
    vector<long long> distance(n, INF);
    distance[source] = 0;
    for (int u : order) {
        if (distance[u] == INF) continue;
        for (auto [v, weight] : adj[u])
            distance[v] = min(distance[v], distance[u] + weight);
    }
    for (long long& value : distance) if (value == INF) value = -1;
    return distance;
}

s15-djisktra-s-algorithm.code:
// Approach: For nonnegative weights, repeatedly pop the smallest tentative distance. Ignore stale
//   heap entries created before a better path was found.
#include <climits>
#include <functional>
#include <queue>
#include <utility>
#include <vector>
using namespace std;
vector<long long> dijkstra(const vector<vector<pair<int,int>>>& adj,
                           int source) {
    const long long INF = LLONG_MAX / 4;
    vector<long long> distance(adj.size(), INF);
    using State = pair<long long,int>; // distance, vertex
    priority_queue<State, vector<State>, greater<State>> pq;
    distance[source] = 0;
    pq.push({0, source});
    while (!pq.empty()) {
        auto [cost, u] = pq.top(); pq.pop();
        if (cost != distance[u]) continue; // obsolete entry
        for (auto [v, weight] : adj[u]) {
            long long candidate = cost + weight; // weights must be nonnegative
            if (candidate >= distance[v]) continue;
            distance[v] = candidate;
            pq.push({candidate, v});
        }
    }
    for (long long& value : distance) if (value == INF) value = -1;
    return distance;
}

s15-why-priority-queue-is-used-in-djiskt.code:
// Approach: A min-priority queue exposes the closest unsettled vertex. Without decrease-key, push an
//   improved copy and skip outdated copies when popped.
#include <functional>
#include <queue>
#include <utility>
#include <vector>
using namespace std;
long long shortestPathTo(const vector<vector<pair<int,int>>>& adj,
                         int source, int target) {
    const long long INF = 4000000000000000000LL;
    vector<long long> distance(adj.size(), INF);
    using State = pair<long long,int>;
    priority_queue<State, vector<State>, greater<State>> pq;
    distance[source] = 0;
    pq.push({0, source});
    while (!pq.empty()) {
        auto [cost, u] = pq.top(); pq.pop();
        if (cost != distance[u]) continue; // no decrease-key needed
        if (u == target) return cost;       // first valid pop is optimal
        for (auto [v, weight] : adj[u]) {
            if (cost + weight < distance[v]) {
                distance[v] = cost + weight;
                pq.push({distance[v], v});
            }
        }
    }
    return -1; // assumes nonnegative weights
}

s15-shortest-path-in-a-binary-maze.code:
// Approach: BFS on four-directional passable cells; each move costs one, so the first visit to the
//   destination is shortest.
#include <queue>
#include <utility>
#include <vector>
using namespace std;
int shortestBinaryMaze(const vector<vector<int>>& grid,
                       pair<int,int> source, pair<int,int> target) {
    int rows = (int)grid.size();
    if (!rows) return -1;
    int cols = (int)grid[0].size();
    auto valid = [&](pair<int,int> p) {
        return p.first >= 0 && p.second >= 0
            && p.first < rows && p.second < cols
            && grid[p.first][p.second] == 1;
    };
    if (!valid(source) || !valid(target)) return -1;
    vector<vector<int>> distance(rows, vector<int>(cols, -1));
    queue<pair<int,int>> q;
    q.push(source);
    distance[source.first][source.second] = 0;
    const int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        if (pair<int,int>{r,c} == target) return distance[r][c];
        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr < 0 || nc < 0 || nr >= rows || nc >= cols
                || grid[nr][nc] == 0 || distance[nr][nc] != -1) continue;
            distance[nr][nc] = distance[r][c] + 1;
            q.push({nr,nc});
        }
    }
    return -1;
}

s15-path-with-minimum-effort.code:
// Approach: Use Dijkstra where a path's cost is its largest height difference so far. Relax a
//   neighbor with max(current effort, edge difference).
#include <algorithm>
#include <climits>
#include <cstdlib>
#include <functional>
#include <queue>
#include <tuple>
#include <vector>
using namespace std;
int minimumEffortPath(const vector<vector<int>>& height) {
    int rows = (int)height.size();
    if (!rows || height[0].empty()) return 0;
    int cols = (int)height[0].size();
    vector<vector<int>> effort(rows, vector<int>(cols, INT_MAX));
    using State = tuple<int,int,int>; // effort, row, column
    priority_queue<State, vector<State>, greater<State>> pq;
    effort[0][0] = 0;
    pq.push({0,0,0});
    const int dr[4] = {1,-1,0,0}, dc[4] = {0,0,1,-1};
    while (!pq.empty()) {
        auto [cost,r,c] = pq.top(); pq.pop();
        if (cost != effort[r][c]) continue;
        if (r == rows - 1 && c == cols - 1) return cost;
        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr < 0 || nc < 0 || nr >= rows || nc >= cols) continue;
            int next = max(cost, abs(height[r][c] - height[nr][nc]));
            if (next < effort[nr][nc]) {
                effort[nr][nc] = next;
                pq.push({next,nr,nc});
            }
        }
    }
    return -1;
}

s15-cheapest-flights-within-k-stops.code:
// Approach: At most k stops means at most k+1 edges. Perform k+1 Bellman-Ford rounds, copying
//   previous distances so one round uses only one more edge.
#include <algorithm>
#include <climits>
#include <tuple>
#include <vector>
using namespace std;
long long findCheapestPrice(int n, const vector<tuple<int,int,int>>& flights,
                            int source, int target, int k) {
    const long long INF = LLONG_MAX / 4;
    vector<long long> distance(n, INF);
    distance[source] = 0;
    for (int edges = 0; edges <= k; ++edges) {
        vector<long long> next = distance; // do not chain two flights in one round
        for (auto [u,v,price] : flights)
            if (distance[u] != INF)
                next[v] = min(next[v], distance[u] + price);
        distance.swap(next);
    }
    return distance[target] == INF ? -1 : distance[target];
}

s15-network-delay-time.code:
// Approach: Run Dijkstra from the source in the directed network. The signal arrival time is the
//   largest shortest-path distance, or -1 if any node is unreachable.
#include <algorithm>
#include <climits>
#include <functional>
#include <queue>
#include <tuple>
#include <utility>
#include <vector>
using namespace std;
long long networkDelayTime(int n, const vector<tuple<int,int,int>>& edges,
                           int source) {
    vector<vector<pair<int,int>>> adj(n + 1);
    for (auto [u,v,weight] : edges) adj[u].push_back({v,weight});
    const long long INF = LLONG_MAX / 4;
    vector<long long> distance(n + 1, INF);
    using State = pair<long long,int>;
    priority_queue<State, vector<State>, greater<State>> pq;
    distance[source] = 0;
    pq.push({0,source});
    while (!pq.empty()) {
        auto [cost,u] = pq.top(); pq.pop();
        if (cost != distance[u]) continue;
        for (auto [v,weight] : adj[u])
            if (cost + weight < distance[v]) {
                distance[v] = cost + weight;
                pq.push({distance[v],v});
            }
    }
    long long answer = 0;
    for (int u = 1; u <= n; ++u) {
        if (distance[u] == INF) return -1;
        answer = max(answer, distance[u]);
    }
    return answer; // nodes are numbered 1 through n
}

s15-number-of-ways-to-arrive-at-destinat.code:
// Approach: Dijkstra computes shortest distances while each relaxation carries the count of shortest
//   paths. Add counts when a different route ties the best distance.
#include <climits>
#include <functional>
#include <queue>
#include <tuple>
#include <utility>
#include <vector>
using namespace std;
int countShortestPaths(int n, const vector<tuple<int,int,int>>& roads) {
    const int MOD = 1000000007;
    if (n <= 0) return 0;
    vector<vector<pair<int,int>>> adj(n);
    for (auto [u,v,time] : roads) {
        adj[u].push_back({v,time});
        adj[v].push_back({u,time});
    }
    const long long INF = LLONG_MAX / 4;
    vector<long long> distance(n, INF);
    vector<int> ways(n, 0);
    using State = pair<long long,int>;
    priority_queue<State, vector<State>, greater<State>> pq;
    distance[0] = 0; ways[0] = 1;
    pq.push({0,0});
    while (!pq.empty()) {
        auto [cost,u] = pq.top(); pq.pop();
        if (cost != distance[u]) continue;
        for (auto [v,time] : adj[u]) {
            long long candidate = cost + time; // roads have positive times
            if (candidate < distance[v]) {
                distance[v] = candidate;
                ways[v] = ways[u];
                pq.push({candidate,v});
            } else if (candidate == distance[v]) {
                ways[v] = (ways[v] + (long long)ways[u]) % MOD;
            }
        }
    }
    return ways[n - 1];
}

s15-minimum-steps-to-reach-end-from-star.code:
// Approach: Each residue modulo 100000 is a BFS state. Multiply by every allowed number, reduce
//   modulo 100000, and mark each residue once.
#include <queue>
#include <vector>
using namespace std;
int minimumMultiplications(const vector<int>& multipliers,
                           int start, int target) {
    const int MOD = 100000;
    start %= MOD; target %= MOD;
    vector<int> distance(MOD, -1);
    queue<int> q;
    distance[start] = 0;
    q.push(start);
    while (!q.empty()) {
        int value = q.front(); q.pop();
        if (value == target) return distance[value];
        for (int factor : multipliers) {
            int next = (int)((long long)value * factor % MOD);
            if (distance[next] != -1) continue;
            distance[next] = distance[value] + 1;
            q.push(next);
        }
    }
    return -1; // assumes nonnegative start and multipliers
}

s15-bellman-ford-algorithm.code:
// Approach: Relax every edge up to V−1 times. A further improving relaxation proves a negative cycle
//   reachable from the source.
#include <algorithm>
#include <climits>
#include <tuple>
#include <utility>
#include <vector>
using namespace std;
pair<bool, vector<long long>> bellmanFord(
    int n, const vector<tuple<int,int,int>>& edges, int source) {
    const long long INF = LLONG_MAX / 4;
    vector<long long> distance(n, INF);
    distance[source] = 0;
    for (int round = 1; round < n; ++round) {
        bool changed = false;
        for (auto [u,v,weight] : edges) {
            if (distance[u] == INF) continue;
            if (distance[u] + weight < distance[v]) {
                distance[v] = distance[u] + weight;
                changed = true;
            }
        }
        if (!changed) break;
    }
    for (auto [u,v,weight] : edges)
        if (distance[u] != INF && distance[u] + weight < distance[v])
            return {false, {}}; // reachable negative cycle
    for (long long& value : distance) if (value == INF) value = -1;
    return {true, distance};
}

s15-floyd-warshal-algorithm.code:
// Approach: Try every vertex as an intermediate point. Improve i→j using i→via→j whenever both
//   subpaths exist.
#include <algorithm>
#include <climits>
#include <vector>
using namespace std;
vector<vector<long long>> floydWarshall(const vector<vector<int>>& matrix) {
    int n = (int)matrix.size();
    const long long INF = LLONG_MAX / 4;
    vector<vector<long long>> dist(n, vector<long long>(n, INF));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (i == j) dist[i][j] = 0;
            else if (matrix[i][j] != -1) dist[i][j] = matrix[i][j];
    for (int via = 0; via < n; ++via)
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (dist[i][via] != INF && dist[via][j] != INF)
                    dist[i][j] = min(dist[i][j],
                                     dist[i][via] + dist[via][j]);
    for (auto& row : dist)
        for (long long& value : row)
            if (value == INF) value = -1;
    return dist; // assumes no negative cycle
}

s15-find-the-city-with-the-smallest-numb.code:
// Approach: Run Floyd-Warshall for all-pairs distances, count neighbors within the threshold, and
//   prefer the larger city index on ties.
#include <algorithm>
#include <climits>
#include <tuple>
#include <vector>
using namespace std;
int findTheCity(int n, const vector<tuple<int,int,int>>& edges,
                int threshold) {
    const long long INF = LLONG_MAX / 4;
    vector<vector<long long>> dist(n, vector<long long>(n, INF));
    for (int i = 0; i < n; ++i) dist[i][i] = 0;
    for (auto [u,v,weight] : edges) {
        dist[u][v] = min(dist[u][v], (long long)weight);
        dist[v][u] = min(dist[v][u], (long long)weight);
    }
    for (int via = 0; via < n; ++via)
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (dist[i][via] != INF && dist[via][j] != INF)
                    dist[i][j] = min(dist[i][j],
                                     dist[i][via] + dist[via][j]);
    int bestCity = -1, fewest = n + 1;
    for (int city = 0; city < n; ++city) {
        int reachable = 0;
        for (int other = 0; other < n; ++other)
            if (other != city && dist[city][other] <= threshold) ++reachable;
        if (reachable <= fewest) { // <= intentionally picks higher index
            fewest = reachable;
            bestCity = city;
        }
    }
    return bestCity;
}

s15-minimum-spanning-tree.code:
// Approach: An MST connects all V vertices with V−1 edges and minimum total weight. Kruskal selects
//   light edges that join different components.
#include <algorithm>
#include <numeric>
#include <tuple>
#include <vector>
using namespace std;
struct DSU {
    vector<int> parent, size;
    explicit DSU(int n) : parent(n), size(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a; size[a] += size[b];
        return true;
    }
};
pair<long long, vector<tuple<int,int,int>>> minimumSpanningTree(
    int n, vector<tuple<int,int,int>> edges) {
    if (n == 0) return {0, {}};
    sort(edges.begin(), edges.end(), [](const auto& a, const auto& b) {
        return get<2>(a) < get<2>(b);
    });
    DSU dsu(n);
    long long weight = 0;
    vector<tuple<int,int,int>> selected;
    for (auto [u,v,cost] : edges)
        if (dsu.unite(u,v)) {
            weight += cost;
            selected.push_back({u,v,cost});
        }
    if ((int)selected.size() != n - 1) return {-1, {}}; // disconnected
    return {weight, selected};
}

s15-prim-s-algorithm.code:
// Approach: Grow a tree from one vertex by repeatedly taking the cheapest edge crossing to an unseen
//   vertex.
#include <functional>
#include <queue>
#include <utility>
#include <vector>
using namespace std;
long long primMST(const vector<vector<pair<int,int>>>& adj) {
    int n = (int)adj.size();
    if (n == 0) return 0;
    vector<char> used(n, false);
    using State = pair<int,int>; // edge weight, new vertex
    priority_queue<State, vector<State>, greater<State>> pq;
    pq.push({0,0});
    long long total = 0;
    int taken = 0;
    while (!pq.empty()) {
        auto [cost,u] = pq.top(); pq.pop();
        if (used[u]) continue; // stale crossing edge
        used[u] = true;
        total += cost;
        ++taken;
        for (auto [v,weight] : adj[u])
            if (!used[v]) pq.push({weight,v});
    }
    return taken == n ? total : -1;
}

s15-disjoint-set-union-by-rank.code:
// Approach: Path compression shortens find paths; union by rank attaches the shallower root under the
//   deeper one.
#include <numeric>
#include <vector>
using namespace std;
class UnionFindRank {
    vector<int> parent, rank;
public:
    explicit UnionFindRank(int n) : parent(n), rank(n, 0) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (rank[a] < rank[b]) swap(a, b);
        parent[b] = a;
        if (rank[a] == rank[b]) ++rank[a];
        return true;
    }
    bool connected(int a, int b) { return find(a) == find(b); }
};

s15-disjoint-set-union-by-size.code:
// Approach: With path compression, attach the smaller component under the larger root and update its
//   size.
#include <numeric>
#include <vector>
using namespace std;
class UnionFindSize {
    vector<int> parent, size;
public:
    explicit UnionFindSize(int n) : parent(n), size(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
    int componentSize(int x) { return size[find(x)]; }
};

s15-kruskal-s-algorithm.code:
// Approach: Sort edges by weight and add an edge only when its endpoints belong to different DSU
//   components.
#include <algorithm>
#include <numeric>
#include <tuple>
#include <vector>
using namespace std;
struct DSU {
    vector<int> parent, size;
    explicit DSU(int n) : parent(n), size(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a; size[a] += size[b];
        return true;
    }
};
long long kruskalMST(int n, vector<tuple<int,int,int>> edges) {
    if (n == 0) return 0;
    sort(edges.begin(), edges.end(), [](const auto& a, const auto& b) {
        return get<2>(a) < get<2>(b);
    });
    DSU dsu(n);
    int chosen = 0;
    long long total = 0;
    for (auto [u,v,weight] : edges)
        if (dsu.unite(u,v)) {
            total += weight;
            ++chosen;
        }
    return chosen == n - 1 ? total : -1; // disconnected graph
}

s15-number-of-operations-to-make-network.code:
// Approach: At least n−1 cables are necessary. If enough exist, union connected computers and use one
//   operation per remaining extra component.
#include <numeric>
#include <utility>
#include <vector>
using namespace std;
struct DSU {
    vector<int> parent, size;
    explicit DSU(int n) : parent(n), size(n,1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) { return parent[x]==x ? x : parent[x]=find(parent[x]); }
    bool unite(int a,int b) {
        a=find(a); b=find(b);
        if (a==b) return false;
        if (size[a]<size[b]) swap(a,b);
        parent[b]=a; size[a]+=size[b];
        return true;
    }
};
int makeConnected(int n, const vector<pair<int,int>>& cables) {
    if (n <= 1) return 0;
    if ((int)cables.size() < n - 1) return -1;
    DSU dsu(n);
    int components = n;
    for (auto [u,v] : cables)
        if (dsu.unite(u,v)) --components;
    return components - 1;
}

s15-most-stones-removed-with-same-rows-o.code:
// Approach: Treat every used row and column as DSU nodes; each stone joins its row to its column.
//   Keep one stone per connected component.
#include <numeric>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>
using namespace std;
struct DSU {
    vector<int> parent, size;
    int add() {
        int id = (int)parent.size();
        parent.push_back(id); size.push_back(1);
        return id;
    }
    int find(int x) { return parent[x]==x ? x : parent[x]=find(parent[x]); }
    void unite(int a,int b) {
        a=find(a); b=find(b);
        if (a==b) return;
        if (size[a]<size[b]) swap(a,b);
        parent[b]=a; size[a]+=size[b];
    }
};
int removeStones(const vector<pair<int,int>>& stones) {
    DSU dsu;
    unordered_map<long long,int> id;
    auto nodeId = [&](long long key) {
        auto it = id.find(key);
        if (it != id.end()) return it->second;
        int created = dsu.add();
        id[key] = created;
        return created;
    };
    for (auto [row,col] : stones) {
        int rowNode = nodeId(2LL * row);
        int colNode = nodeId(2LL * col + 1);
        dsu.unite(rowNode, colNode); // row and column namespaces differ
    }
    unordered_set<int> roots;
    for (const auto& [key,node] : id) roots.insert(dsu.find(node));
    return (int)stones.size() - (int)roots.size();
}

s15-accounts-merge.code:
// Approach: Union account indices whenever they share an email. Group all emails by DSU root, sort
//   them, and prefix each group with its owner name.
#include <algorithm>
#include <numeric>
#include <string>
#include <unordered_map>
#include <vector>
using namespace std;
struct DSU {
    vector<int> parent, size;
    explicit DSU(int n):parent(n),size(n,1) {
        iota(parent.begin(),parent.end(),0);
    }
    int find(int x) { return parent[x]==x ? x : parent[x]=find(parent[x]); }
    void unite(int a,int b) {
        a=find(a); b=find(b);
        if(a==b)return;
        if(size[a]<size[b])swap(a,b);
        parent[b]=a;size[a]+=size[b];
    }
};
vector<vector<string>> accountsMerge(const vector<vector<string>>& accounts) {
    int n = (int)accounts.size();
    DSU dsu(n);
    unordered_map<string,int> owner;
    for (int i=0;i<n;++i)
        for (int j=1;j<(int)accounts[i].size();++j) {
            auto [it, inserted] = owner.emplace(accounts[i][j],i);
            if (!inserted) dsu.unite(i,it->second);
        }
    vector<vector<string>> emails(n);
    for (const auto& [email,index] : owner)
        emails[dsu.find(index)].push_back(email);
    vector<vector<string>> answer;
    for (int i=0;i<n;++i) {
        if (dsu.find(i)!=i) continue;
        sort(emails[i].begin(),emails[i].end());
        vector<string> merged{accounts[i][0]};
        merged.insert(merged.end(),emails[i].begin(),emails[i].end());
        answer.push_back(merged); // also preserves accounts with no email
    }
    return answer;
}

s15-number-of-island-ii.code:
// Approach: Turn cells into land one by one. Each new cell creates an island, then union it with
//   neighboring land and subtract one per successful merge.
#include <numeric>
#include <utility>
#include <vector>
using namespace std;
struct DSU {
    vector<int> parent, size;
    explicit DSU(int n):parent(n),size(n,1) {
        iota(parent.begin(),parent.end(),0);
    }
    int find(int x) { return parent[x]==x?x:parent[x]=find(parent[x]); }
    bool unite(int a,int b) {
        a=find(a);b=find(b);
        if(a==b)return false;
        if(size[a]<size[b])swap(a,b);
        parent[b]=a;size[a]+=size[b];
        return true;
    }
};
vector<int> numIslands2(int rows,int cols,
                        const vector<pair<int,int>>& additions) {
    DSU dsu(rows*cols);
    vector<char> land(rows*cols,false);
    vector<int> answer;
    int islands=0;
    const int dr[4]={1,-1,0,0},dc[4]={0,0,1,-1};
    for(auto [r,c]:additions) {
        int id=r*cols+c;
        if(land[id]) { answer.push_back(islands); continue; }
        land[id]=true; ++islands;
        for(int i=0;i<4;++i) {
            int nr=r+dr[i],nc=c+dc[i];
            if(nr<0||nc<0||nr>=rows||nc>=cols)continue;
            int neighbor=nr*cols+nc;
            if(land[neighbor]&&dsu.unite(id,neighbor))--islands;
        }
        answer.push_back(islands);
    }
    return answer;
}

s15-making-a-large-island.code:
// Approach: Union all existing land. For each zero, sum the sizes of its distinct neighboring
//   components plus one for the flipped cell.
#include <algorithm>
#include <numeric>
#include <set>
#include <vector>
using namespace std;
struct DSU {
    vector<int> parent,size;
    explicit DSU(int n):parent(n),size(n,1) {
        iota(parent.begin(),parent.end(),0);
    }
    int find(int x) { return parent[x]==x?x:parent[x]=find(parent[x]); }
    void unite(int a,int b) {
        a=find(a);b=find(b);
        if(a==b)return;
        if(size[a]<size[b])swap(a,b);
        parent[b]=a;size[a]+=size[b];
    }
    int componentSize(int x) { return size[find(x)]; }
};
int largestIsland(const vector<vector<int>>& grid) {
    int rows=(int)grid.size();
    if(!rows)return 0;
    int cols=(int)grid[0].size();
    DSU dsu(rows*cols);
    const int dr[4]={1,-1,0,0},dc[4]={0,0,1,-1};
    for(int r=0;r<rows;++r)
        for(int c=0;c<cols;++c)if(grid[r][c]) {
            if(r+1<rows&&grid[r+1][c])dsu.unite(r*cols+c,(r+1)*cols+c);
            if(c+1<cols&&grid[r][c+1])dsu.unite(r*cols+c,r*cols+c+1);
        }
    int best=0;
    for(int r=0;r<rows;++r)for(int c=0;c<cols;++c) {
        if(grid[r][c]) {
            best=max(best,dsu.componentSize(r*cols+c));
            continue;
        }
        set<int> adjacent; // do not count one island twice
        for(int i=0;i<4;++i) {
            int nr=r+dr[i],nc=c+dc[i];
            if(nr>=0&&nc>=0&&nr<rows&&nc<cols&&grid[nr][nc])
                adjacent.insert(dsu.find(nr*cols+nc));
        }
        int candidate=1;
        for(int root:adjacent)candidate+=dsu.size[root];
        best=max(best,candidate);
    }
    return best;
}

s15-swim-in-rising-water.code:
// Approach: Dijkstra minimizes the maximum elevation encountered along a path. The first time the
//   destination leaves the min-heap gives the least required water level.
#include <algorithm>
#include <climits>
#include <functional>
#include <queue>
#include <tuple>
#include <vector>
using namespace std;
int swimInWater(const vector<vector<int>>& grid) {
    int rows=(int)grid.size();
    if(!rows||grid[0].empty())return -1;
    int cols=(int)grid[0].size();
    vector<vector<int>>best(rows,vector<int>(cols,INT_MAX));
    using State=tuple<int,int,int>; // required level, row, column
    priority_queue<State,vector<State>,greater<State>>pq;
    best[0][0]=grid[0][0];pq.push({grid[0][0],0,0});
    const int dr[4]={1,-1,0,0},dc[4]={0,0,1,-1};
    while(!pq.empty()) {
        auto [level,r,c]=pq.top();pq.pop();
        if(level!=best[r][c])continue;
        if(r==rows-1&&c==cols-1)return level;
        for(int i=0;i<4;++i) {
            int nr=r+dr[i],nc=c+dc[i];
            if(nr<0||nc<0||nr>=rows||nc>=cols)continue;
            int next=max(level,grid[nr][nc]);
            if(next<best[nr][nc]) {
                best[nr][nc]=next;
                pq.push({next,nr,nc});
            }
        }
    }
    return -1;
}

s15-bridges-in-graph.code:
// Approach: Tarjan's low-link value records the earliest discovery reachable from a subtree. An edge
//   u–v is a bridge when low[v] > tin[u].
#include <algorithm>
#include <functional>
#include <utility>
#include <vector>
using namespace std;
vector<pair<int,int>> criticalConnections(
    int n,const vector<pair<int,int>>&edges) {
    vector<vector<pair<int,int>>>adj(n);
    for(int id=0;id<(int)edges.size();++id) {
        auto [u,v]=edges[id];
        adj[u].push_back({v,id});
        adj[v].push_back({u,id});
    }
    vector<int>tin(n,-1),low(n);
    vector<pair<int,int>>bridges;
    int timer=0;
    function<void(int,int)> dfs=[&](int u,int parentEdge) {
        tin[u]=low[u]=timer++;
        for(auto [v,id]:adj[u]) {
            if(id==parentEdge)continue; // edge ID handles parallel edges
            if(tin[v]!=-1) low[u]=min(low[u],tin[v]);
            else {
                dfs(v,id);
                low[u]=min(low[u],low[v]);
                if(low[v]>tin[u])bridges.push_back({min(u,v),max(u,v)});
            }
        }
    };
    for(int u=0;u<n;++u)if(tin[u]==-1)dfs(u,-1);
    sort(bridges.begin(),bridges.end());
    return bridges;
}

s15-articulation-point.code:
// Approach: A non-root vertex is an articulation point when one child cannot reach above it
//   (low[child] >= tin[parent]); a DFS root needs at least two children.
#include <algorithm>
#include <functional>
#include <utility>
#include <vector>
using namespace std;
vector<int> articulationPoints(int n,const vector<pair<int,int>>&edges) {
    vector<vector<pair<int,int>>>adj(n);
    for(int id=0;id<(int)edges.size();++id) {
        auto [u,v]=edges[id];
        adj[u].push_back({v,id});
        adj[v].push_back({u,id});
    }
    vector<int>tin(n,-1),low(n);
    vector<char>cut(n,false);
    int timer=0;
    function<void(int,int)> dfs=[&](int u,int parentEdge) {
        tin[u]=low[u]=timer++;
        int children=0;
        for(auto [v,id]:adj[u]) {
            if(id==parentEdge)continue;
            if(tin[v]!=-1)low[u]=min(low[u],tin[v]);
            else {
                ++children;
                dfs(v,id);
                low[u]=min(low[u],low[v]);
                if(parentEdge!=-1&&low[v]>=tin[u])cut[u]=true;
            }
        }
        if(parentEdge==-1&&children>1)cut[u]=true;
    };
    for(int u=0;u<n;++u)if(tin[u]==-1)dfs(u,-1);
    vector<int>answer;
    for(int u=0;u<n;++u)if(cut[u])answer.push_back(u);
    return answer;
}

s15-kosaraju-s-algorithm.code:
// Approach: DFS finishing order identifies which component to process first. Reverse all edges and
//   DFS in reverse finishing order to extract SCCs.
#include <algorithm>
#include <vector>
using namespace std;
void finishingDfs(int u,const vector<vector<int>>&adj,
                  vector<char>&seen,vector<int>&order) {
    seen[u]=true;
    for(int v:adj[u])if(!seen[v])finishingDfs(v,adj,seen,order);
    order.push_back(u); // finish after descendants
}
void componentDfs(int u,const vector<vector<int>>&reverse,
                  vector<char>&seen,vector<int>&part) {
    seen[u]=true;part.push_back(u);
    for(int v:reverse[u])if(!seen[v])componentDfs(v,reverse,seen,part);
}
vector<vector<int>> stronglyConnectedComponents(
    const vector<vector<int>>&adj) {
    int n=(int)adj.size();
    vector<char>seen(n,false);
    vector<int>order;
    for(int u=0;u<n;++u)if(!seen[u])finishingDfs(u,adj,seen,order);
    vector<vector<int>>reverse(n);
    for(int u=0;u<n;++u)
        for(int v:adj[u])reverse[v].push_back(u);
    fill(seen.begin(),seen.end(),false);
    vector<vector<int>>answer;
    for(int i=n-1;i>=0;--i) {
        int u=order[i];
        if(seen[u])continue;
        vector<int>part;
        componentDfs(u,reverse,seen,part);
        answer.push_back(part);
    }
    return answer;
}
